UPDATE public.transacciones t SET estado=c.estado, match_id=c.match_id, confianza=c.confianza
FROM cambios c WHERE t.id=c.id;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM public.transacciones WHERE estado='conciliada' AND match_id IS NULL) THEN
    RAISE EXCEPTION 'conciliación confirmada sin contraparte';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.transacciones a LEFT JOIN public.transacciones b ON b.id=a.match_id
    WHERE a.match_id IS NOT NULL AND (b.id IS NULL OR b.match_id IS DISTINCT FROM a.id OR b.fuente=a.fuente)
  ) THEN RAISE EXCEPTION 'conciliación no recíproca'; END IF;
END $$;